package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.nio.charset.Charset;
import java.nio.charset.CharsetEncoder;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.jsoup.Jsoup;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Tag;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class Document_title_TriageGen0Test {

    private Document doc;

    @Before
    public void setup() {
        doc = Jsoup.parse("<html><head><title>Some title</title></head><body></body></html>");
    }

    @Test
    public void test_title() {
        // Test normal case
        assertEquals("Some title", doc.title());

        // Test null title element
        Document doc2 = Jsoup.parse("<html><head><meta name=\"title\" content=\"Some title\"/></head><body></body></html>");
        assertEquals("", doc2.title());

        // Test no title element
        Document doc3 = Jsoup.parse("<html><head></head><body></body></html>");
        assertEquals("", doc3.title());

        // Test multiple title elements
        Document doc4 = Jsoup.parse("<html><head><title>Some title</title><title>Another title</title></head><body></body></html>");
        assertEquals("Some title", doc4.title());
    }












}

